'use server';
/**
 * @fileOverview This file defines a Genkit flow for generating a donor recognition report based on specified criteria.
 *
 * @exports generateDonorRecognitionReport - An async function to trigger the donor recognition report generation flow.
 * @exports GenerateDonorRecognitionReportInput - The input type for the generateDonorRecognitionReport function.
 * @exports GenerateDonorRecognitionReportOutput - The output type for the generateDonorRecognitionReport function.
 */

import {ai} from '@/ai/genkit';
import {z} from 'genkit';

const GenerateDonorRecognitionReportInputSchema = z.object({
  criteria: z.string().describe('The criteria for donor recognition, such as donation frequency, amount, or other factors.'),
  reportFormat: z.enum(['text', 'markdown', 'json']).default('text').describe('The desired format for the report (text, markdown, or JSON).'),
});
export type GenerateDonorRecognitionReportInput = z.infer<typeof GenerateDonorRecognitionReportInputSchema>;

const GenerateDonorRecognitionReportOutputSchema = z.object({
  report: z.string().describe('The generated donor recognition report in the specified format.'),
});
export type GenerateDonorRecognitionReportOutput = z.infer<typeof GenerateDonorRecognitionReportOutputSchema>;

export async function generateDonorRecognitionReport(input: GenerateDonorRecognitionReportInput): Promise<GenerateDonorRecognitionReportOutput> {
  return generateDonorRecognitionReportFlow(input);
}

const prompt = ai.definePrompt({
  name: 'generateDonorRecognitionReportPrompt',
  input: {
    schema: GenerateDonorRecognitionReportInputSchema,
  },
  output: {
    schema: GenerateDonorRecognitionReportOutputSchema,
  },
  prompt: `You are an expert at creating donor recognition reports for non-profit organizations.

  Based on the following criteria: {{{criteria}}},
  generate a report recognizing donors. The report should be formatted as {{{reportFormat}}}.`,
});

const generateDonorRecognitionReportFlow = ai.defineFlow(
  {
    name: 'generateDonorRecognitionReportFlow',
    inputSchema: GenerateDonorRecognitionReportInputSchema,
    outputSchema: GenerateDonorRecognitionReportOutputSchema,
  },
  async input => {
    const {output} = await prompt(input);
    return output!;
  }
);
